package com.fileservice

import akka.actor.ActorSystem
import akka.http.scaladsl.Http
import akka.http.scaladsl.model._
import akka.http.scaladsl.model.headers.Location
import akka.http.scaladsl.server.Directives._
import akka.http.scaladsl.server.Route
import akka.stream.ActorMaterializer
import java.net.{URI, URLDecoder}
import java.nio.charset.StandardCharsets
import scala.concurrent.{ExecutionContext, Future, Promise}
import scala.util.{Success, Failure}

object FileProcessingService {

  implicit val system: ActorSystem = ActorSystem("file-service")
  implicit val materializer: ActorMaterializer = ActorMaterializer()
  implicit val ec: ExecutionContext = system.dispatcher

  private val shutdownPromise = Promise[Unit]()
  @volatile private var isShuttingDown = false

  private val ALLOWED_HOSTS = Set(
    "files.internal.company.com",
    "cdn.company.com",
    "assets.company.com"
  )

  private val SERVICE_BASE = "https://files.internal.company.com"

  // Normalize URL to handle encoding variations
  private def normalizeUrl(url: String): String = {
    val decoded = URLDecoder.decode(url, StandardCharsets.UTF_8.name())
    decoded.replaceAll("\\s+", "").toLowerCase
  }

  // Extract the effective host from a URL, handling edge cases
  private def extractHost(url: String): Option[String] = {
    try {
      val normalized = normalizeUrl(url)
      val uri = new URI(normalized)
      val host = uri.getHost
      if (host != null) Some(host)
      else {
        // Fallback: parse authority manually for protocol-relative URLs
        val authorityPattern = """^(?:[a-z]+:)?//([^/:?#]+)""".r
        authorityPattern.findFirstMatchIn(normalized).map(_.group(1))
      }
    } catch {
      case _: Exception => None
    }
  }

  // Validate that a redirect target is within allowed domains
  private def isAllowedRedirect(target: String): Boolean = {
    extractHost(target) match {
      case Some(host) =>
        ALLOWED_HOSTS.exists(allowed => host.endsWith(allowed))
      case None =>
        // Relative URLs are safe
        !target.contains("://") && !target.startsWith("//")
    }
  }

  // Build the redirect URL for processed files
  private def buildRedirectUrl(fileId: String, destination: Option[String]): String = {
    destination match {
      case Some(dest) if isAllowedRedirect(dest) => dest
      case _ => s"$SERVICE_BASE/files/$fileId/download"
    }
  }

  // Simulate file processing
  private def processFile(fileId: String): Future[Boolean] = {
    Future {
      Thread.sleep(100)
      !isShuttingDown
    }
  }

  val routes: Route = {
    pathPrefix("api" / "v1") {
      path("process" / Segment) { fileId =>
        parameters("callback".?) { callback =>
          get {
            if (isShuttingDown) {
              complete(StatusCodes.ServiceUnavailable, "Service is shutting down")
            } else {
              onComplete(processFile(fileId)) {
                case Success(true) =>
                  val redirectUrl = buildRedirectUrl(fileId, callback)
                  redirect(Uri(redirectUrl), StatusCodes.TemporaryRedirect)
                case Success(false) =>
                  complete(StatusCodes.ServiceUnavailable, "Processing interrupted")
                case Failure(ex) =>
                  complete(StatusCodes.InternalServerError, ex.getMessage)
              }
            }
          }
        }
      } ~
      path("health") {
        get {
          if (isShuttingDown)
            complete(StatusCodes.ServiceUnavailable, "shutting down")
          else
            complete(StatusCodes.OK, "healthy")
        }
      } ~
      path("shutdown") {
        post {
          isShuttingDown = true
          shutdownPromise.trySuccess(())
          complete(StatusCodes.OK, "Shutdown initiated")
        }
      }
    }
  }

  def main(args: Array[String]): Unit = {
    val bindingFuture = Http().bindAndHandle(routes, "0.0.0.0", 8080)
    bindingFuture.onComplete {
      case Success(binding) =>
        println(s"Server online at ${binding.localAddress}")
        shutdownPromise.future.onComplete { _ =>
          binding.unbind().onComplete(_ => system.terminate())
        }
      case Failure(ex) =>
        println(s"Failed to bind: ${ex.getMessage}")
        system.terminate()
    }
  }
}
